from typing import Dict


def classify_mechanism(rho1: float, rho2: float, n: int,
                       tol: float = 0.01) -> Dict[str, object]:
    """Identify the generating mechanism from the first two lags alone.

    Trichotomy of profile shapes:

        pure density  : rho(1) = 0,        rho(2) = 0          (flat)
        Markov        : rho(1) = lambda,   rho(2) = lambda^2   (geometric)
        coincidence   : rho(1) > 0,        rho(2) = 0          (one spike)

    A geometric profile vanishing at lag 2 must already vanish at lag 1, so the
    one-spike shape is genuinely non-Markov.  The zeros beyond lag 1 of the
    coincidence scan hold for EVERY latent rate curve, whereas its lag-1 height
    can be any value in (0,1); hence shape identifies and amplitude does not.

    Complexity: O(1).
    """
    forced = -1.0 / (n - 1)
    a1, a2 = rho1 - forced, rho2 - forced   # remove the centring artefact
    if abs(a1) <= tol and abs(a2) <= tol:
        return {"mechanism": "pure density", "shape": "flat",
                "artefact_level": forced, "lambda": None}
    if abs(a1) > tol and abs(a2) <= tol:
        return {"mechanism": "coincidence (MA-1)", "shape": "one spike",
                "artefact_level": forced, "lambda": None, "spike": a1}
    if abs(a2 - a1 * a1) <= tol:
        return {"mechanism": "Markov", "shape": "geometric",
                "artefact_level": forced, "lambda": a1}
    return {"mechanism": "unclassified", "shape": "other",
            "artefact_level": forced, "lambda": None}

