INPUT : rate window [l, u] with 0 < l <= u < 1; length n
OUTPUT: maximum achievable spike Sigma and an attaining rate curve

// closed form of the spike from three latent rates a, b, c:
//     rho(1) = c (1 - b) / (1 - a b)         (a b cancels!)
// monotone: increasing in a, increasing in c, decreasing in b

Sigma <- u * (1 - l) / (1 - u * l)

for j = 0 to n-1 do
    curve[j] <- (j odd) ? l : u              // alternating u, l, u, l
end for

assert spike_height(curve[0], curve[1], curve[2]) == Sigma  // sharp

// supremum over ALL curves in (0,1):
//   Sigma(t, 1-t) = (1-t)^2 / (1 - t(1-t))  ->  1  as t -> 0,
//   while every curve has rho(1) < 1, so sup = 1, not attained.
return Sigma, curve
